<?php

namespace App\Mcp;

use Monolog\Attribute\WithMonologChannel;
use Nelmio\ApiDocBundle\ApiDocGenerator;
use Psr\Log\LoggerInterface;
use Symfony\Component\DependencyInjection\Attribute\Autowire;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpKernel\HttpKernelInterface;

/**
 * Exposes every operation of the OpenAPI spec (generated by Nelmio) as an MCP tool.
 * Path/query parameters and body properties are flattened into a single inputSchema.
 */
#[WithMonologChannel('mcp')]
class ApiToolRegistry
{
    private const string REF_PREFIX = '#/components/schemas/';
    private const array HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete'];

    /** @var array<string, array{definition: array, method: string, path: string, params: array<string, string>}>|null */
    private ?array $tools = null;

    public function __construct(
        #[Autowire(service: 'nelmio_api_doc.generator.default')]
        private ApiDocGenerator $generator,
        private HttpKernelInterface $kernel,
        private LoggerInterface $logger,
    ) {
    }

    /**
     * @return list<array> MCP tool definitions, as returned by tools/list
     */
    public function definitions(): array
    {
        return array_column($this->tools(), 'definition');
    }

    /**
     * Runs the API operation as an internal sub-request and returns an MCP CallToolResult.
     *
     * @throws \InvalidArgumentException when the tool doesn't exist
     */
    public function call(string $name, array $arguments): array
    {
        $tool = $this->tools()[$name] ?? throw new \InvalidArgumentException(\sprintf('Unknown tool: %s', $name));

        $path = $tool['path'];
        $query = [];
        foreach ($tool['params'] as $param => $in) {
            if ('path' === $in) {
                $path = str_replace('{'.$param.'}', rawurlencode((string) ($arguments[$param] ?? '')), $path);
            } elseif (isset($arguments[$param])) {
                $query[$param] = $arguments[$param];
            }
            unset($arguments[$param]);
        }

        $request = Request::create(
            $path.($query ? '?'.http_build_query($query) : ''),
            strtoupper($tool['method']),
            server: ['CONTENT_TYPE' => 'application/json', 'HTTP_ACCEPT' => 'application/json'],
            content: 'get' === $tool['method'] ? null : json_encode((object) $arguments),
        );
        $start = microtime(true);
        $response = $this->kernel->handle($request, HttpKernelInterface::SUB_REQUEST);
        $this->logger->info('Sous-requête API', [
            'tool' => $name,
            'request' => $request->getMethod().' '.$request->getRequestUri(),
            'status' => $response->getStatusCode(),
            'ms' => (int) ((microtime(true) - $start) * 1000),
        ]);
        $this->logger->debug('Réponse API', ['body' => $response->getContent()]);

        // API errors (404, 422...) go back to the model as a tool result so it can correct its call.
        return [
            'content' => [['type' => 'text', 'text' => (string) $response->getContent()]],
            'isError' => $response->getStatusCode() >= 400,
        ];
    }

    private function tools(): array
    {
        if (null !== $this->tools) {
            return $this->tools;
        }

        $spec = json_decode($this->generator->generate()->toJson(), true);
        $schemas = $spec['components']['schemas'] ?? [];
        $this->tools = [];

        foreach ($spec['paths'] as $path => $operations) {
            foreach (array_intersect_key($operations, array_flip(self::HTTP_METHODS)) as $method => $operation) {
                $params = [];
                $properties = [];
                $required = [];
                foreach ($operation['parameters'] ?? [] as $parameter) {
                    if (!\in_array($parameter['in'], ['path', 'query'], true)) {
                        continue;
                    }
                    $params[$parameter['name']] = $parameter['in'];
                    $properties[$parameter['name']] = $this->resolve($parameter['schema'] ?? [], $schemas);
                    if ($parameter['required'] ?? false) {
                        $required[] = $parameter['name'];
                    }
                }

                $body = $this->resolve($operation['requestBody']['content']['application/json']['schema'] ?? [], $schemas);
                if ($collisions = array_intersect_key($properties, $body['properties'] ?? [])) {
                    throw new \LogicException(\sprintf('Operation "%s": body properties collide with parameters (%s).', $operation['operationId'], implode(', ', array_keys($collisions))));
                }
                $properties += $body['properties'] ?? [];
                $required = [...$required, ...$body['required'] ?? []];

                $this->tools[$operation['operationId']] = [
                    'definition' => [
                        'name' => $operation['operationId'],
                        'description' => $operation['summary'] ?? $operation['description'] ?? $operation['operationId'],
                        // Objects, not arrays, so empty values still encode as {} in JSON.
                        'inputSchema' => ['type' => 'object', 'properties' => (object) $properties, 'required' => $required],
                        'annotations' => ['readOnlyHint' => 'get' === $method],
                    ],
                    'method' => $method,
                    'path' => $path,
                    'params' => $params,
                ];
            }
        }

        return $this->tools;
    }

    // ponytail: inlines $ref recursively, a self-referencing schema would loop forever; switch to $defs if one appears.
    private function resolve(array $schema, array $schemas): array
    {
        if (isset($schema['$ref'])) {
            return $this->resolve($schemas[substr($schema['$ref'], \strlen(self::REF_PREFIX))], $schemas);
        }

        return array_map(fn ($value) => \is_array($value) ? $this->resolve($value, $schemas) : $value, $schema);
    }
}
